    c->r[R_AX] = ds_get(c, 0xBA3C); c->r[R_DX] = ds_get(c, 0xBA3E); ds_put(c, (uint16_t)(c->r[R_BX] + 0xB094), c->r[R_AX]); ds_put(c, (uint16_t)(c->r[R_BX] + 0xB096), c->r[R_DX]);
