    SM4_NEED(1, 0x2C79); VG3_NEAR(0xC831, 0x2C7C, 4); c->r[R_BX] = cpu_pop16(c); c->r[R_BX] = cpu_pop16(c); c->r[R_SI] = (uint16_t)alu_add(c, c->r[R_SI], c->r[R_AX], 1, 0);
