    ds_put(c, 0x3D98, c->r[R_AX]); ds_put(c, 0xA098, c->r[R_AX]); ds_put(c, 0x40B0, c->r[R_AX]); ds_put(c, 0x40AE, c->r[R_AX]); ds_put(c, 0xC09E, 3);
