    c->r[R_BX] = seg_read16(c, c->seg[S_ES], (uint16_t)(c->r[R_BX] + 0x38)); c->r[R_BX] = (uint16_t)x86_shift(c, 4, c->r[R_BX], 1, 1);
    c->r[R_AX] = ds_get(c, (uint16_t)(c->r[R_BX] + 0x3DAA)); ds_put(c, 0xB19A, c->r[R_AX]);
