    SM4_NEED(1, 0x3C8A); VG3_NEAR(0xC67A, 0x3C8D, 4); VG3_DROP(6); VG3_SETFRAME(0xFFF6, c->r[R_AX]); alu_sub(c, ds_get(c, 0xC0D0), c->r[R_AX], 1, 0); c->icount += 4;
