        SM4_NEED(1, 0x3CA0); VG3_NEAR(0xEF68, 0x3CA3, 2); ds_put(c, 0xBA3C, c->r[R_AX]); ds_put(c, 0xBA3E, c->r[R_DX]); c->icount += 2;
