    c->r[R_AX]=bp_get(c,STRENGTH);c->r[R_AX]=TADD(c->r[R_AX],TDS(0x3D8A));TCMP(c->r[R_AX],0x64);
    if(x86_cond(c,14))goto gauge_colour_low;
    TB(2,0x64B3);
