    ds_put8(c,(uint16_t)(c->r[R_BX]+0xB2D6),(uint8_t)alu_op(c,4,ds_get8(c,(uint16_t)(c->r[R_BX]+0xB2D6)),0xEF,0));
    ds_put(c,(uint16_t)(c->r[R_BX]+0xB2D8),(uint16_t)alu_op(c,5,GBXDS(0xB2D8),0x10,1));
    if(x86_cond(c,9))goto leave;
