    RB(2,0x0516);c->r[R_AX]=0x6D8C;RP(c->r[R_AX]);
    RNEAR(0x051A,0x1992,0x051D);
    RB(2,0x051D);RDROP();bp_put(c,-10,(uint16_t)alu_inc(c,bp_get(c,-10),1));
