    RB(3,0x0523);c->r[R_AX]=ds_get(c,0x54B8);alu_op(c,7,bp_get(c,-10),c->r[R_AX],1);
    if(x86_cond(c,2))goto prepare_record;
    RB(1,0x052B);goto done;
