    c->r[R_AX]=VD(0x12);ds_put(c,0x85FA,c->r[R_AX]);c->r[R_AX]=VD(0x0E);ds_put(c,0x85FC,c->r[R_AX]);
    c->r[R_AX]=VD(0x14);ds_put(c,0x85FE,c->r[R_AX]);c->r[R_AX]=VD(0x10);ds_put(c,0x8600,c->r[R_AX]);
