    XB(2, 0x1590);
    alu_op(c, 7, c->r[R_CX], 1, 1);
    if (x86_cond(c, 4)) goto last_cr;
    XB(2, 0x1595);
    alu_op(c, 7, ds_get8(c, c->r[R_SI]), 0x0A, 0);
    if (x86_cond(c, 4)) goto step;                                      /* CR LF: the CR is dropped */
    XB(1, 0x159A);
    goto keep;
last_cr:
    XB(2, 0x159C);
    alu_logic(c, ds_get8(c, XFLAG()) & 0x40, 0);
    if (x86_cond(c, 4)) goto file_cr;
    XN(2, 0x15A3);
    c->r[R_AX] = 0x4400;
