    XINT(0x15C4);                                                       /* one byte more from the file */
    XB(1, 0x15C6);
    if (x86_cond(c, 2)) goto restore;
    XB(2, 0x15C8);
    c->r[R_AX] = (uint16_t)alu_op(c, 1, c->r[R_AX], c->r[R_AX], 1);
    if (x86_cond(c, 4)) goto store_cr;                                  /* nothing more: keep the CR */
    XB(2, 0x15CC);
