    c->r[R_AX] = 0x4201;
    XINT(0x15DA);                                                       /* back one byte */
    XB(3, 0x15DC);
    c->r[R_CX] = 0x0001;
    alu_op(c, 7, bp_get8(c, ONE_BYTE), 0x0A, 0);
    if (x86_cond(c, 4)) goto drop_cr;
