#define OP(v_) cpu_push16(c, (v_))
#define OSP(n_) (c->r[R_SP] = (uint16_t)alu_op(c, 0, c->r[R_SP], (n_), 1))
#define ORUN(call_) do { const uint64_t until_ = m->run_until; \
    if (m->run_until > c->stop_at) m->run_until = c->stop_at; \
