#define ONEAR(at_, target_, ret_) do { SM4_NEED(1, (at_)); ORUN(guest_call_pop(m, (target_), (ret_), 0)); } while (0)
    if (!room(c, 7)) return 0;
    OB(7, 0x27CA);
    c->r[R_AX] = DEPARTURE_TIME; OP(c->r[R_AX]);
